  arcPulseB=new THREE.LineLoop(_arcRingGeo, lm(0xffb066,0.6));
  arcApex=new THREE.Line(makeArcGeo(2), lm(0xffd24a,0.9));                    // horizontal tangent line at the parabola's apex (max height)
